script:
// Excel 导出 - 二维数组表头示例
// 查询数据
var data = db.select("select id, username, email, create_time from sys_user where is_del = 0 limit 10")

// 二维数组表头：[[字段名，列名], ...]
var headers = [
    ["id", "ID"],
    ["username", "用户名"],
    ["email": "邮箱"],
    ["create_time", "创建时间"]
]

// 导出 Excel（二维数组方式）
var excelBytes = excel.write(data, headers)

// 设置响应头下载
response.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
response.setHeader("Content-Disposition", "attachment;filename=" + URLEncoder.encode("用户导出.xlsx", "UTF-8"))
response.write(excelBytes)
